const express = require('express');
const fs = require('fs');
const path = require('path');
const app = express();
const VIDEO_DIR = '/srv/edu/videos';
const QUALITIES = ['480p', '720p', '1080p'];

app.get('/lectures/:lectureId/stream', (req, res) => {
  const { lectureId } = req.params;
  const quality = req.query.q || '720p';
  if (!/^[A-Z]{2}\d{4}$/.test(lectureId)) return res.status(400).end();
  if (!QUALITIES.includes(quality)) return res.status(400).end();
  const file = path.join(VIDEO_DIR, lectureId, `${quality}.mp4`);
  const stat = fs.statSync(file);
  res.writeHead(200, { 'Content-Length': stat.size, 'Content-Type': 'video/mp4' });
  fs.createReadStream(file).pipe(res);
});

app.listen(3000);

const express = require('express');
const fs = require('fs');
const path = require('path');
const app = express();
const VIDEO_DIR = '/srv/edu/vod';

app.get('/vod/play', (req, res) => {
  const course = req.query.course;
  const file = req.query.file;
  const range = req.headers.range;
  if (!['safety', 'ethics', 'privacy'].includes(course)) return res.sendStatus(404);
  const full = path.join(VIDEO_DIR, course, file);
  const { size } = fs.statSync(full);
  if (range) {
    const [s, e] = range.replace(/bytes=/, '').split('-');
    const start = parseInt(s, 10);
    const end = e ? parseInt(e, 10) : size - 1;
    res.writeHead(206, {
      'Content-Range': `bytes ${start}-${end}/${size}`,
      'Accept-Ranges': 'bytes',
      'Content-Length': end - start + 1,
      'Content-Type': 'video/mp4',
    });
    fs.createReadStream(full, { start, end }).pipe(res);
  } else {
    res.writeHead(200, { 'Content-Length': size, 'Content-Type': 'video/mp4' });
    fs.createReadStream(full).pipe(res);
  }
});

app.listen(3000);

