const express = require('express');
const axios = require('axios');
const app = express();
const cache = new Map();

app.get('/proxy', async (req, res) => {
  const target = req.query.url;
  if (cache.has(target)) return res.json(cache.get(target));
  try {
    const r = await axios.get(target, { timeout: 3000 });
    cache.set(target, r.data);
    res.json(r.data);
  } catch (e) {
    res.status(502).json({ error: 'upstream' });
  }
});

app.listen(3000);

const express = require('express');
const app = express();
const ALLOWED_HOSTS = new Set(['apis.data.go.kr', 'openapi-seoul.example.go.kr']);
const cache = new Map();

app.get('/proxy/open', async (req, res) => {
  let u;
  try {
    u = new URL(req.query.url);
  } catch {
    return res.status(400).end();
  }
  if (u.protocol !== 'https:' || !ALLOWED_HOSTS.has(u.hostname)) return res.status(403).end();
  if (cache.has(u.href)) return res.json(cache.get(u.href));
  const r = await fetch(u);
  const data = await r.json();
  cache.set(u.href, data);
  res.json(data);
});

app.listen(3000);

