const express = require('express');
const app = express();
const cache = new Map();
const ENDPOINT = 'https://apis.data.go.kr/1613000/BusSttnInfo/getStationList';

app.get('/bus/stations', async (req, res) => {
  const { city, keyword } = req.query;
  const ttl = Math.min(Number(req.query.ttl) || 60, 600) * 1000;
  const url = new URL(ENDPOINT);
  url.searchParams.set('cityCode', city);
  url.searchParams.set('nodeNm', keyword);
  const k = url.toString();
  const hit = cache.get(k);
  if (hit && hit.exp > Date.now()) return res.json(hit.data);
  const r = await fetch(url);
  const data = await r.json();
  cache.set(k, { data, exp: Date.now() + ttl });
  res.json(data);
});

app.listen(3000);

